import { FC } from 'react';
import { StoreStats, StoreConfig } from '../types';

interface StatsSummaryProps {
  stats?: StoreStats[];
  storeConfigs?: StoreConfig[];
}

const StatsSummary: FC<StatsSummaryProps> = ({
  stats = [],
  storeConfigs = [],
}) => {
  return (
    <div className="stats-grid">
      {stats.map((stat) => {
        const config = storeConfigs.find((c) => c.id === stat.id);
        const storeColor = config ? config.color : '#3b82f6';

        return (
          <div key={stat.id} className="stat-card">
            <div className="stat-store-header">
              <span
                className="stat-dot"
                style={{ backgroundColor: storeColor }}
              />
              <h3 className="stat-store-name">{stat.name}</h3>
            </div>

            <div className="stat-metrics">
              <div className="metric-row">
                <span className="metric-label">期間合計来客数</span>
                <span className="metric-value">
                  {stat.total.toLocaleString()} 人
                </span>
              </div>

              <div className="metric-row">
                <span className="metric-label">月平均来客数</span>
                <span className="metric-value">
                  {stat.average.toLocaleString()} 人
                </span>
              </div>

              <div className="metric-row">
                <span className="metric-label">最高来客月</span>
                <span className="metric-value metric-highlight">
                  {stat.maxMonth} ({stat.maxVal.toLocaleString()} 人)
                </span>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default StatsSummary;

import { FC } from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { MonthlyRecord, StoreConfig } from '../types';

interface VisitorChartProps {
  data?: MonthlyRecord[];
  stores?: StoreConfig[];
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
    dataKey: string;
  }>;
  label?: string;
  stores: StoreConfig[];
}

const CustomTooltip: FC<CustomTooltipProps> = ({
  active,
  payload,
  label,
  stores,
}) => {
  if (active && payload && payload.length > 0) {
    return (
      <div className="custom-tooltip">
        <p className="tooltip-month">{label}</p>
        {payload.map((entry) => {
          const store = stores.find((s) => s.id === entry.dataKey);
          const storeName = store ? store.name : entry.name;
          return (
            <div key={entry.dataKey} className="tooltip-item">
              <span style={{ color: entry.color, fontWeight: 600 }}>
                {storeName}:
              </span>
              <span>{Number(entry.value).toLocaleString()} 人</span>
            </div>
          );
        })}
      </div>
    );
  }
  return null;
};

const formatYAxis = (tickItem: number): string => {
  return `${(tickItem / 1000).toFixed(0)}k人`;
};

const VisitorChart: FC<VisitorChartProps> = ({
  data = [],
  stores = [],
}) => {
  return (
    <div className="chart-card">
      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={data}
            margin={{ top: 20, right: 30, left: 10, bottom: 10 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
            <XAxis
              dataKey="month"
              tickLine={false}
              stroke="#64748b"
              tick={{ fontSize: 13, fill: '#475569' }}
            />
            <YAxis
              tickLine={false}
              stroke="#64748b"
              tickFormatter={formatYAxis}
              tick={{ fontSize: 13, fill: '#475569' }}
            />
            <Tooltip content={<CustomTooltip stores={stores} />} />
            <Legend
              formatter={(value: string) => {
                const store = stores.find((s) => s.id === value);
                return (
                  <span style={{ color: '#334155', fontWeight: 600, fontSize: '0.9rem' }}>
                    {store ? store.name : value}
                  </span>
                );
              }}
            />
            {stores.map((store) => {
              if (!store.isVisible) {
                return null;
              }
              return (
                <Line
                  key={store.id}
                  type="monotone"
                  dataKey={store.id}
                  name={store.name}
                  stroke={store.color}
                  strokeWidth={3}
                  activeDot={{ r: 7, strokeWidth: 0 }}
                  dot={{ r: 4, strokeWidth: 2, fill: '#ffffff', stroke: store.color }}
                />
              );
            })}
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default VisitorChart;

import { FC, useState, useMemo } from 'react';
import { StoreConfig, FilterPeriod, StoreStats, StoreId } from './types';
import { INITIAL_STORE_CONFIGS, INITIAL_MONTHLY_DATA } from './mockData';
import VisitorChart from './components/VisitorChart';
import StatsSummary from './components/StatsSummary';
import './index.css';

const App: FC = () => {
  const [storeConfigs, setStoreConfigs] = useState<StoreConfig[]>(INITIAL_STORE_CONFIGS);
  const [period, setPeriod] = useState<FilterPeriod>('all');

  const filteredMonthlyData = useMemo(() => {
    if (period === 'first-half') {
      return INITIAL_MONTHLY_DATA.slice(0, 6);
    }
    if (period === 'second-half') {
      return INITIAL_MONTHLY_DATA.slice(6, 12);
    }
    return INITIAL_MONTHLY_DATA;
  }, [period]);

  const statsList = useMemo<StoreStats[]>(() => {
    return storeConfigs
      .filter((config) => config.isVisible)
      .map((config) => {
        const storeKey = config.id as StoreId;
        const total = filteredMonthlyData.reduce(
          (sum, record) => sum + record[storeKey],
          0
        );
        const average = filteredMonthlyData.length > 0
          ? Math.round(total / filteredMonthlyData.length)
          : 0;

        let maxMonth = '';
        let maxVal = -1;

        filteredMonthlyData.forEach((record) => {
          const val = record[storeKey];
          if (val > maxVal) {
            maxVal = val;
            maxMonth = record.month;
          }
        });

        return {
          id: config.id,
          name: config.name,
          total,
          average,
          maxMonth,
          maxVal: maxVal >= 0 ? maxVal : 0,
        };
      });
  }, [storeConfigs, filteredMonthlyData]);

  const handleToggleStore = (storeId: StoreId) => {
    setStoreConfigs((prev) =>
      prev.map((store) =>
        store.id === storeId ? { ...store, isVisible: !store.isVisible } : store
      )
    );
  };

  const handleReset = () => {
    setStoreConfigs(INITIAL_STORE_CONFIGS);
    setPeriod('all');
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">店舗別月間来客数比較ダッシュボード</h1>
        <p className="subtitle">
          渋谷店・新宿店・池袋店の月別来客データを折れ線グラフで視覚的に比較・分析できます。
        </p>
      </header>

      <div className="controls-panel">
        <div className="control-group">
          <span className="control-label">表示店舗:</span>
          <div className="store-toggles">
            {storeConfigs.map((store) => (
              <label key={store.id} className="store-checkbox-label">
                <input
                  type="checkbox"
                  checked={store.isVisible}
                  onChange={() => handleToggleStore(store.id)}
                />
                <span
                  className="store-color-badge"
                  style={{ backgroundColor: store.color }}
                />
                <span>{store.name}</span>
              </label>
            ))}
          </div>
        </div>

        <div className="control-group">
          <span className="control-label">期間:</span>
          <div className="period-tabs">
            <button
              type="button"
              className={period === 'all' ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setPeriod('all')}
            >
              通年 (1〜12月)
            </button>
            <button
              type="button"
              className={period === 'first-half' ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setPeriod('first-half')}
            >
              上半期 (1〜6月)
            </button>
            <button
              type="button"
              className={period === 'second-half' ? 'tab-btn tab-btn-active' : 'tab-btn'}
              onClick={() => setPeriod('second-half')}
            >
              下半期 (7〜12月)
            </button>
          </div>
          <button
            type="button"
            className="reset-btn"
            onClick={handleReset}
          >
            初期状態に戻す
          </button>
        </div>
      </div>

      <VisitorChart
        data={filteredMonthlyData}
        stores={storeConfigs}
      />

      <StatsSummary
        stats={statsList}
        storeConfigs={storeConfigs}
      />
    </div>
  );
};

export default App;
